/*!
 * \file sparse_flash_attention_gqa_tiling.cpp
 * \brief
 */
#include "ai_infra_sparse_flash_attention_gqa_tiling.h"
#include "error/ops_error.h"
#include "tiling/tiling_api.h"
#include "platform/platform_info.h"
#include "ai_infra_sparse_flash_attention_gqa_tiling_v3.h"
#include "register/device_op_impl_registry.h"

using namespace ge;
using namespace AscendC;
namespace optiling {
namespace optilingSfa {
ge::graphStatus TilingAiInfraSparseFlashAttentionGqa(gert::TilingContext *context)
{
    if (context == nullptr) {
        OPS_LOG_E("AiInfraSparseFlashAttentionGqa", "tiling context is nullptr!");
        return ge::GRAPH_FAILED;
    }

    if (RouteToSfa(context)) {
        return TilingAiInfraSparseFlashAttentionGqaV3(context);
    }
    return ge::GRAPH_FAILED;
}

SFA_EXTERN_C ge::graphStatus DoOpTilingAiInfraSparseFlashAttentionGqa(gert::TilingContext *context)
{
    OPS_CHECK(context == nullptr,
              OPS_REPORT_VECTOR_INNER_ERR("AiInfraSparseFlashAttentionGqa", "Tiling context is null."),
              return ge::GRAPH_FAILED);

    auto platformInfoPtr = context->GetPlatformInfo();
    OPS_CHECK(platformInfoPtr == nullptr,
              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "platformInfoPtr is null"),
              return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
    auto socShortName = ascendcPlatform.GetSocVersion();
    if (socShortName == platform_ascendc::SocVersion::ASCEND910_55) {
        return ge::GRAPH_FAILED;
    } else {
        return TilingAiInfraSparseFlashAttentionGqa(context);
    }
    return ge::GRAPH_SUCCESS;
}

extern "C" {
__attribute__((visibility("default"))) ge::graphStatus DeviceDoOpTilingAiInfraSparseFlashAttentionGqa(
    gert::TilingContext *context)
{
    return DoOpTilingAiInfraSparseFlashAttentionGqa(context);
}
}

} // namespace optilingSfa
DEVICE_IMPL_OP_OPTILING(AiInfraSparseFlashAttentionGqa)
    .Tiling(optiling::optilingSfa::DeviceDoOpTilingAiInfraSparseFlashAttentionGqa);
} // namespace optiling

